<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Illuminate\Http\JsonResponse; use Illuminate\Support\Facades\Http; use Pterodactyl\Models\ConsoleCommand; use Pterodactyl\Models\Server; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\CommandHistoryRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\ShareConsoleLogRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\StoreCommandHistoryRequest; class ConsoleController extends ClientApiController { private const PASTE_LIMIT = 500_000; private const PASTE_ENDPOINT = 'https://paste.rs/'; public function history(CommandHistoryRequest $request, Server $server): JsonResponse { return new JsonResponse([ 'items' => ConsoleCommand::recent($request->user()->id, $server->id), 'keep' => ConsoleCommand::KEEP, 'keepDays' => ConsoleCommand::KEEP_DAYS, ]); } public function store(StoreCommandHistoryRequest $request, Server $server): JsonResponse { $command = trim($request->input('command')); if ($command === '') { return new JsonResponse(['recorded' => false]); } ConsoleCommand::remember($request->user()->id, $server->id, $command); return new JsonResponse(['recorded' => true]); } public function clear(CommandHistoryRequest $request, Server $server): JsonResponse { ConsoleCommand::query() ->where('user_id', $request->user()->id) ->where('server_id', $server->id) ->delete(); return new JsonResponse(['cleared' => true]); } public function share(ShareConsoleLogRequest $request, Server $server): JsonResponse { $content = trim($request->input('content')); if ($content === '') { return new JsonResponse( ['errors' => [['code' => 'EmptyLog', 'detail' => 'There is nothing in the console to share.']]], 422 ); } if (strlen($content) > self::PASTE_LIMIT) { $content = "[earlier output trimmed to fit]\n" . substr($content, -self::PASTE_LIMIT); } try { $response = Http::withBody($content, 'text/plain')->timeout(15)->post(self::PASTE_ENDPOINT); } catch (\Throwable $exception) { return new JsonResponse( ['errors' => [['code' => 'PasteUnreachable', 'detail' => 'The paste service could not be reached.']]], 502 ); } if ($response->failed()) { return new JsonResponse( ['errors' => [['code' => 'PasteFailed', 'detail' => 'The paste service rejected the log.']]], 502 ); } return new JsonResponse(['url' => trim($response->body())]); } } 